import{_ as o,o as t,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.4.13 View Workspace Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-13-view-workspace-profile/spec.md","filePath":"feature/agency-workspace/3-4-13-view-workspace-profile/spec.md"}'),i={name:"feature/agency-workspace/3-4-13-view-workspace-profile/spec.md"};function s(n,e,c,l,d,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-4-13-view-workspace-profile" tabindex="-1">3.4.13 View Workspace Profile <a class="header-anchor" href="#_3-4-13-view-workspace-profile" aria-label="Permalink to &quot;3.4.13 View Workspace Profile&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.4.13</td></tr><tr><td>Feature</td><td>View Workspace Profile</td></tr><tr><td>Domain</td><td>Agency &amp; Workspace (FR 3.4)</td></tr><tr><td>Role</td><td>MANAGER / CREATOR / CLIENT</td></tr><tr><td>Version</td><td>2.3 — 2026-09-23 — rewritten to the standard FR format</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when a Workspace member opens the profile of a Workspace.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Workspace members with role MANAGER, CREATOR, or CLIENT.</li><li><strong>Purpose:</strong> Shows the Workspace&#39;s details — timezone configuration and branding/company information — so members understand which timezone the Workspace runs on and how its branding is configured.</li><li><strong>Interface:</strong> Workspace settings screen at <code>/workspaces/:id/settings</code> (<code>WorkspaceSettingsPage</code>) — a single combined page that also hosts the update form (FR 3.4.14); there is no separate read-only <code>/profile</code> route in the current frontend.</li><li><strong>Data Processing:</strong> The system loads the Workspace via <code>WorkspaceController.getWorkspace</code> (<code>@RequireRole({MANAGER, CREATOR, CLIENT})</code> on the controller), and maps the record to a Workspace profile, parsing the stored settings into timezone, default platforms, and report frequency.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Workspace Settings Screen (<code>WorkspaceSettingsPage</code>):</p><ul><li>Logo block (<code>LogoUploader</code>) shown only when <code>canManage</code> is true — see BA conflict note below.</li><li>Form pre-filled from <code>GET /api/v1/workspaces/:id</code>: name, timezone (<code>TimezoneSelect</code>), default platforms (<code>PlatformToggle</code>), report frequency (<code>FrequencyToggle</code>), industry, company size, website, phone, location.</li><li>⚠ BA conflict (needs team decision): the frontend computes <code>canManage</code> by calling <code>listMembers</code> and checking the caller&#39;s role for <code>OWNER</code> or <code>MANAGER</code>. The backend&#39;s workspace-level <code>MemberRole</code> enum only has MANAGER / CREATOR / CLIENT (no workspace OWNER — OWNER exists only at Agency level per FR 3.4.12). The FE check for a workspace-level &quot;OWNER&quot; role can never be true against the current backend data, so in practice only MANAGER unlocks editing/logo/danger-zone controls; the OWNER branch looks like dead/stale FE code, not a real access path. Flagging rather than assuming intent.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Workspace identifier; the caller&#39;s authenticated identity.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The Workspace record; the caller&#39;s active membership row; the stored settings payload (timezone, default platforms).</li><li><strong>Output:</strong> The Workspace profile — id, name, agencyId, slug, ownerId, settings (timezone, defaultPlatforms, reportFrequency), industry, companySize, website, phone, location, description, brandColor, logoIcon, logoUrl, tagline, foundedYear, facebookUrl, linkedinUrl, instagramUrl, isActive, createdAt.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-29:</strong> Multi-tenancy — every workspace-scoped resource carries workspaceId; a caller with no active membership in the Workspace cannot read it regardless of system role (except ADMIN, cross-workspace). Enforced in two layers: (1) <code>@RequireRole({MANAGER, CREATOR, CLIENT})</code> on <code>WorkspaceController.getWorkspace</code>, checked by <code>RequireRoleAspect</code> against a fresh DB read of the caller&#39;s <em>global</em> role set before the service method runs — a caller who holds none of those workspace roles anywhere is rejected here with 403 <code>FORBIDDEN</code>; (2) inside <code>WorkspaceServiceImpl.getWorkspace</code>, an explicit <code>assertMember(workspaceId, currentUser.getId())</code> call that re-checks membership in <em>this specific</em> Workspace and throws 403 <code>WORKSPACE_ACCESS_DENIED</code> if the caller is not an active member of it. The service-level check is what actually scopes the check to the requested Workspace.</li><li>Workspace that does not exist → 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>Caller not an active member of that specific Workspace → 403 <code>WORKSPACE_ACCESS_DENIED</code> (service-level check).</li><li>Failure to parse the stored settings falls back to empty settings (no timezone, no default platforms) without raising an error.</li><li>There is a single Workspace-level timezone configuration — not one per Client or per Task.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>The Workspace must exist; otherwise 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>The caller must hold an active membership in that Workspace (BR-29); otherwise 403 <code>WORKSPACE_ACCESS_DENIED</code>.</li><li>A malformed settings payload must degrade to empty settings rather than fail the request.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>Member opens <code>/workspaces/:id/settings</code>.</li><li>System loads the Workspace; if it does not exist, the request fails with 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>System confirms the caller has an active membership in that Workspace (BR-29); otherwise the request fails with 403 <code>WORKSPACE_ACCESS_DENIED</code>.</li><li>System maps the Workspace to its profile, parsing the stored settings into timezone, default platforms, and report frequency.</li><li>Screen displays the Workspace profile, including the Workspace timezone.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: The Workspace does not exist → 404 <code>WORKSPACE_NOT_FOUND</code>, toast MSG38. 2.a2: The member returns to the Workspace list and picks a valid Workspace.</li><li>3.a1: The caller has no active membership in that Workspace (BR-29) → 403 <code>WORKSPACE_ACCESS_DENIED</code>, toast MSG40. 3.a2: The member returns to the Workspace list; only Workspaces they belong to are shown.</li><li>4.a1: Stored settings are malformed → the screen shows empty settings instead of failing. 4.a2: No further action is needed; the member may ask a MANAGER to re-save the settings.</li><li>Workspace serves Clients across several locations → still a single Workspace-level timezone; per-Campaign timezones are outside the current scope.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>No data is changed; the Workspace profile is displayed.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Timezone per Task or per Campaign (only one Workspace-level timezone is in scope).</li><li>A media package template or an active-Client list on the profile — neither exists in the current data returned, and their inclusion is not yet decided.</li><li>A dedicated read-only profile view — the current frontend renders view and edit (FR 3.4.14) on the same <code>/workspaces/:id/settings</code> screen; splitting them is a future UX decision, not part of this FR.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p><a href="./../../../BA/01-organization-structure.html">01-organization-structure.md</a>, <a href="./../../../BA/03-agency-workspace-management.html">03-agency-workspace-management.md</a></p>',27)])])}const m=o(i,[["render",s]]);export{u as __pageData,m as default};
